    input [1:0] sel,
    input enable,
    output reg [3:0] mux_out
);

always @(*) begin
    if (!enable) begin
        mux_out = 4'b0000;
    end else begin
        case (sel)
            2'b00: mux_out = data0;
            2'b01: mux_out = data1;
            2'b10: mux_out = data2;
