{"bug_description": "Multiple drivers on one variable: `shift_reg` is assigned in two separate `always` blocks (load vs. shift), which is invalid for a single `reg`; merge load and shift behavior into one clocked `always` with a `case` on `state` (or equivalent).", "buggy_rtl": "module UART_TX (
    input clk,
    input rst_n,
    input [7:0] tx_data,
    input tx_start,
    output reg tx_out,
    output reg tx_busy
);

reg [2:0] bit_counter;
reg [7:0] shift_reg;
reg [3:0] state;

localparam IDLE = 0, START_BIT = 1, DATA_BITS = 2, STOP_BIT = 3;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 8'h00;
    end else if (tx_start && (state == IDLE)) begin
        shift_reg <= tx_data;  // Load new data
    end
end

always @(posedge clk) begin
    if (state == DATA_BITS) begin
        shift_reg <= {1'b0, shift_reg[7:1]};  // Right shift
    end
end

// State machine and output logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        tx_out <= 1'b1;
        tx_busy <= 1'b0;
        bit_counter <= 3'b0;
    end else begin
        case (state)
            IDLE: begin
                if (tx_start) begin
                    state <= START_BIT;
                    tx_out <= 1'b0;  // Start bit
                    tx_busy <= 1'b1;
                end
            end
            START_BIT: state <= DATA_BITS;
            DATA_BITS: begin
                tx_out <= shift_reg[0];
                if (bit_counter == 7) begin
                    state <= STOP_BIT;
                    bit_counter <= 0;
                end else begin
                    bit_counter <= bit_counter + 1;
                end
            end
            STOP_BIT: begin
                tx_out <= 1'b1;  // Stop bit
                state <= IDLE;
                tx_busy <= 1'b0;
            end
        endcase
    end
end

endmodule", "case_id": "case_008_2d795521", "previous_actions": [], "replay": {"backend": "iverilog", "compile_command": "iverilog -g2012 -o buggy.vvp dut.sv tb.sv", "compile_returncode": 0, "compiler_output": "", "note": "the supplied testbench passes against the buggy revision, so it does not detect the defect", "per_backend": {"iverilog": "passed"}, "run_command": "vvp buggy.vvp", "run_returncode": 0, "simulation_output": "[stdout]
