    output reg  [2:0]  state
);

    // 状态编码
    localparam IDLE      = 3'd0;
    localparam LOAD      = 3'd1;
    localparam CHECK     = 3'd2;
    localparam SEND      = 3'd3;
    localparam WAIT_ACK  = 3'd4;
    localparam RETRY     = 3'd5;
    localparam SYNC      = 3'd6;

    reg [1:0] retry_cnt;
    reg [2:0] next_state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = LOAD;
                else
                    next_state = IDLE;
            end

            LOAD: begin
                next_state = CHECK;
            end

            CHECK: begin
                if (ready)
                    next_state = SEND;
                else
                    next_state = CHECK;
            end

            SEND: begin
                next_state = WAIT_ACK;
            end

            WAIT_ACK: begin
                if (ack)
                    next_state = IDLE;
                else if (retry_cnt < 2)
                    next_state = RETRY;
                else
                    next_state = SYNC;
            end

            RETRY: begin
                next_state = SEND;
            end

            SYNC: begin
                if (sync_done)
                    next_state = IDLE;
                else
                    next_state = SYNC;
            end

            default: next_state = IDLE;
        endcase
    end

    // retry
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            retry_cnt <= 0;
        else if (state == WAIT_ACK && !ack)
            retry_cnt <= retry_cnt + 1;
        else if (state == IDLE)
            retry_cnt <= 0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tx_valid <= 0;
        else if (state == SEND)
            tx_valid <= 1;
        else
            tx_valid <= 0;
    end

