          idle    = 0;
          playing = 0;
          paused  = 1;
          if (playButton) begin
            next_state = PLAYING;
          end else if (stopButton) begin
            next_state = STOPPED;
          end else begin
            next_state = PAUSED;
          end
        end
      default:
        begin
          idle    = 1;
          playing = 0;
          paused  = 0;
          next_state = IDLE;
        end
    endcase
  end
endmodule
