  output reg        issue_read,
  output reg  [4:0] line_ptr,
  output reg        cal_valid,
  output reg  [2:0] lane_state
);

  localparam ST_BOOT  = 3'd0;
  localparam ST_SEEK  = 3'd1;
  localparam ST_CAL   = 3'd2;
  localparam ST_FETCH = 3'd3;
  localparam ST_PAD   = 3'd4;
  localparam ST_DONE  = 3'd5;

  reg [2:0] ns;
  reg [1:0] beat;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      lane_state <= ST_BOOT;
      line_ptr   <= 5'd0;
      beat       <= 2'd0;
    end else begin
      lane_state <= ns;
      if (ns == ST_FETCH && rom_rdy)
        line_ptr <= line_ptr + 1'b1;
      if (ns == ST_SEEK)
        beat <= beat + 1'b1;
      else if (ns == ST_BOOT)
        beat <= 2'd0;
    end
  end

  always @(*) begin
    issue_read  = 1'b0;
    cal_valid   = 1'b0;
    ns          = lane_state;

    case (lane_state)
      ST_BOOT: begin
        if (kick)
          ns = ST_SEEK;
        else
          ns = ST_BOOT;
      end

      ST_SEEK: begin
        if (beat == 2'd3)
          ns = ST_FETCH;
        else
          ns = ST_SEEK;
      end

      ST_CAL: begin
        cal_valid  = 1'b1;
        issue_read = 1'b1;
        if (rom_rdy)
          ns = ST_FETCH;
        else
          ns = ST_CAL;
      end

      ST_FETCH: begin
        issue_read = 1'b1;
        if (line_ptr == 5'd18)
          ns = ST_PAD;
        else
          ns = ST_FETCH;
      end

      ST_PAD: begin
        if (rom_data == 8'hFF)
          ns = ST_DONE;
        else
          ns = ST_FETCH;
      end

      ST_DONE: begin
        ns = ST_DONE;
      end

      default: ns = ST_BOOT;
    endcase
  end

endmodule
