{"bug_description": "Livelock: Both channels repeatedly receive short grants that rotate on every cycle, so neither accumulates the required dwell cycles to complete its transaction. The interface stays busy with perpetual handshakes but no forward progress toward txn_done.", "buggy_rtl": "module fabric_slice_arb (
  input  wire       clk,
  input  wire       rst_n,
  input  wire       req_a,
  input  wire       req_b,
  input  wire       cancel_a,
  input  wire       cancel_b,
  output reg        gnt_a,
  output reg        gnt_b,
  output reg        txn_done,
  output reg  [1:0] rot_token
);

  localparam DWELL_NEED = 3'd4;

  reg        active_a, active_b;
  reg  [2:0] hold_a, hold_b;
  reg        latch_done;

  always @(req_a or req_b or cancel_a or cancel_b or rot_token) begin
    active_a = req_a & ~cancel_a;
    active_b = req_b & ~cancel_b;
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rot_token <= 2'b01;
      hold_a    <= 3'd0;
      hold_b    <= 3'd0;
      gnt_a     <= 1'b0;
      gnt_b     <= 1'b0;
      latch_done<= 1'b0;
    end else begin
      if (gnt_a)
        hold_a <= hold_a + 1'b1;
      else
        hold_a <= 3'd0;

      if (gnt_b)
        hold_b <= hold_b + 1'b1;
      else
        hold_b <= 3'd0;

      if ((hold_a == DWELL_NEED) || (hold_b == DWELL_NEED))
        latch_done <= 1'b1;

      gnt_a <= 1'b0;
      gnt_b <= 1'b0;
      if (active_a && rot_token[0]) begin
        gnt_a <= 1'b1;
      end else if (active_b && rot_token[1]) begin
        gnt_b <= 1'b1;
      end

      if (active_a | active_b) begin
        rot_token <= {rot_token[0], rot_token[1]};
      end else begin
        rot_token <= 2'b01;
        hold_a <= 3'd0;
        hold_b <= 3'd0;
        latch_done <= 1'b0;
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      txn_done <= 1'b0;
    else
      txn_done <= latch_done;
  end

endmodule
