  output reg   [2:0] dbg_state,
  output reg   [4:0] tick_cnt,
  output reg         seq_done,
  output reg         late_phase
);

  localparam ST_IDLE    = 3'd0;
  localparam ST_GATHER  = 3'd1;
  localparam ST_ISSUE   = 3'd2;
  localparam ST_WAIT    = 3'd3;
  localparam ST_DRAIN   = 3'd4;

  reg [2:0] ns;
  reg [4:0] shadow_len;
  reg       armed_d;
  reg       seen_issue;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      dbg_state  <= ST_IDLE;
      tick_cnt   <= 5'd0;
      shadow_len <= 5'd0;
      armed_d    <= 1'b0;
      seen_issue <= 1'b0;
    end else begin
      dbg_state  <= ns;
      armed_d    <= tick_arm;
      if (ns == ST_IDLE) begin
        tick_cnt   <= 5'd0;
        shadow_len <= {2'd0, burst_len};
        seen_issue <= 1'b0;
      end else if (ns == ST_ISSUE) begin
        seen_issue <= 1'b1;
        tick_cnt   <= tick_cnt + 1'b1;
      end else if (ns == ST_DRAIN)
        seen_issue <= 1'b0;
    end
