    seq_done   = 1'b0;
    late_phase = 1'b0;
    ns         = dbg_state;

    case (dbg_state)
      ST_IDLE: begin
        if (stream_en)
          ns = ST_GATHER;
        else
          ns = ST_IDLE;
      end
      ST_GATHER: begin
        if (burst_len != 3'd0)
          ns = ST_ISSUE;
        else
          ns = ST_IDLE;
      end
      ST_ISSUE: begin
        if (armed_d && tick_cnt + 1'b1 >= shadow_len)
          ns = ST_WAIT;
        else if (!armed_d && tick_cnt >= shadow_len)
          ns = ST_WAIT;
        else
          ns = ST_ISSUE;
