      ST_WAIT: begin
        late_phase = seq_done;
        if (late_phase && !seq_done)
          ns = ST_DRAIN;
        else
          ns = ST_WAIT;
      end
      ST_DRAIN: begin
        seq_done = 1'b1;
        if (!stream_en)
          ns = ST_IDLE;
        else
          ns = ST_DRAIN;
      end
      default: ns = ST_IDLE;
    endcase
  end

endmodule
