  output reg  [2:0] arq_ps,
  output reg        grant_vld,
  output reg        defer_a,
  output reg        defer_b,
  output reg  [3:0] hop_ctr
);

  localparam Q_IDLE  = 3'd0;
  localparam Q_PING  = 3'd1;
  localparam Q_PONG  = 3'd2;
  localparam Q_GRANT = 3'd3;
  localparam Q_COOL  = 3'd4;

  reg [2:0] ns;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      arq_ps   <= Q_IDLE;
      grant_vld <= 1'b0;
      defer_a  <= 1'b0;
      defer_b  <= 1'b0;
      hop_ctr  <= 4'd0;
    end else begin
      arq_ps <= ns;
      if (ns == Q_IDLE) begin
        hop_ctr <= 4'd0;
      end else if (ns == Q_PING || ns == Q_PONG)
        hop_ctr <= hop_ctr + 1'b1;
      else if (ns == Q_GRANT)
        grant_vld <= 1'b1;
      else if (ns == Q_COOL)
        grant_vld <= 1'b0;
    end
  end

  always @(*) begin
    defer_a  = 1'b0;
    defer_b  = 1'b0;
    ns       = arq_ps;

    case (arq_ps)
      Q_IDLE: begin
        if (policy_en && (ch_a | ch_b))
          ns = Q_PING;
        else
          ns = Q_IDLE;
      end
      Q_PING: begin
        defer_a = ch_a;
        defer_b = ch_b;
        if (ch_a && ch_b)
          ns = Q_PONG;
        else
          ns = Q_GRANT;
      end
      Q_PONG: begin
        defer_a = ch_b;
        defer_b = ch_a;
        if (ch_a && ch_b)
          ns = Q_PING;
        else
          ns = Q_GRANT;
      end
      Q_GRANT: begin
        ns = Q_COOL;
      end
      Q_COOL: begin
        if (!policy_en)
          ns = Q_IDLE;
        else
          ns = Q_COOL;
      end
      default: ns = Q_IDLE;
    endcase
  end

endmodule
