module testbench;
  import config_pkg::*;
  logic clk, rst_n, test_en;
  logic [1:0][4:0] raddr;
  logic [1:0][31:0] rdata;
  logic [1:0][4:0] waddr;
  logic [1:0][31:0] wdata;
  logic [1:0] we;

  localparam config_pkg::cva6_cfg_t Cfg = '{
    default: '0,
    NrCommitPorts: unsigned'(2),
    NrLoadBufEntries: unsigned'(2),
    AxiAddrWidth: unsigned'(64),
    AxiDataWidth: unsigned'(64),
    AxiIdWidth: unsigned'(4),
    AxiUserWidth: unsigned'(64)
  };

  ariane_regfile_fpga #(
    .CVA6Cfg(Cfg),
    .DATA_WIDTH(32),
    .NR_READ_PORTS(2),
    .ZERO_REG_ZERO(1'b1)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .test_en_i(test_en),
    .raddr_i(raddr),
    .rdata_o(rdata),
    .waddr_i(waddr),
    .wdata_i(wdata),
    .we_i(we)
  );

  always #5 clk = ~clk;

  initial begin
    clk = 0;
    rst_n = 0;
    test_en = 0;
    raddr[0] = 5'd1;
    raddr[1] = 5'd2;
    waddr[0] = 5'd1;
    waddr[1] = 5'd2;
    wdata[0] = 32'h1111;
    wdata[1] = 32'h2222;
    we = 2'b00;
    #12 rst_n = 1;
    @(posedge clk);
    we = 2'b11;
    @(posedge clk);
    we = 2'b00;
    @(posedge clk);
    if (rdata[0] !== 32'h1111) begin
      $display("FAIL p0");
      $finish(1);
    end
    $display("=====Passed=====");
    $finish(0);
  end
endmodule
