// Minimal interconnect: one host, fixed one-cycle response from slaves.
module bus #(
  parameter int unsigned NrDevices = 3,
  parameter int unsigned NrHosts   = 1,
  parameter int unsigned DataWidth = 32,
  parameter int unsigned AddressWidth = 32
) (
  input  logic                     clk_i,
  input  logic                     rst_ni,
  input  logic                     host_req_i   [NrHosts],
  output logic                     host_gnt_o   [NrHosts],
  input  logic [AddressWidth-1:0]  host_addr_i  [NrHosts],
  input  logic                     host_we_i    [NrHosts],
  input  logic [DataWidth/8-1:0]   host_be_i    [NrHosts],
  input  logic [DataWidth-1:0]     host_wdata_i [NrHosts],
  output logic                     host_rvalid_o[NrHosts],
  output logic [DataWidth-1:0]     host_rdata_o [NrHosts],
  output logic                     host_err_o   [NrHosts],
  output logic                     device_req_o [NrDevices],
  output logic [AddressWidth-1:0]  device_addr_o[NrDevices],
  output logic                     device_we_o  [NrDevices],
  output logic [DataWidth/8-1:0]   device_be_o  [NrDevices],
  output logic [DataWidth-1:0]     device_wdata_o[NrDevices],
  input  logic                     device_rvalid_i[NrDevices],
  input  logic [DataWidth-1:0]     device_rdata_i [NrDevices],
  input  logic                     device_err_i [NrDevices],
  input  logic [AddressWidth-1:0]  cfg_device_addr_base [NrDevices],
  input  logic [AddressWidth-1:0]  cfg_device_addr_mask [NrDevices]
);
  for (genvar h = 0; h < NrHosts; h++) begin : g_host
    assign host_gnt_o[h] = host_req_i[h];
    assign host_err_o[h] = 1'b0;
    logic [NrDevices-1:0] hit;
    for (genvar d = 0; d < NrDevices; d++) begin : g_hit
      assign hit[d] = ((host_addr_i[h] & cfg_device_addr_mask[d]) == cfg_device_addr_base[d]);
    end
    always_comb begin
      device_req_o = '0;
      device_addr_o = '{default: '0};
      device_we_o = '0;
      device_be_o = '{default: '0};
      device_wdata_o = '{default: '0};
      if (host_req_i[h]) begin
        for (int d = 0; d < NrDevices; d++) begin
          if (hit[d]) begin
            device_req_o[d] = 1'b1;
            device_addr_o[d] = host_addr_i[h];
            device_we_o[d] = host_we_i[h];
            device_be_o[d] = host_be_i[h];
            device_wdata_o[d] = host_wdata_i[h];
          end
        end
      end
    end
    logic [DataWidth-1:0] rdata_mux;
    logic rvalid_mux;
    always_comb begin
      rdata_mux = '0;
      rvalid_mux = 1'b0;
      for (int d = 0; d < NrDevices; d++) begin
        if (hit[d] && device_rvalid_i[d]) begin
          rdata_mux = device_rdata_i[d];
          rvalid_mux = 1'b1;
        end
      end
    end
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        host_rvalid_o[h] <= 1'b0;
        host_rdata_o[h]  <= '0;
      end else begin
        host_rvalid_o[h] <= rvalid_mux;
        host_rdata_o[h]  <= rdata_mux;
      end
    end
  end
endmodule

module ram_2p #(
  parameter int Depth = 1024,
  parameter string MemInitFile = ""
) (
  input  logic        clk_i,
  input  logic        rst_ni,
  input  logic        a_req_i,
  input  logic        a_we_i,
  input  logic [3:0]  a_be_i,
  input  logic [31:0] a_addr_i,
  input  logic [31:0] a_wdata_i,
  output logic        a_rvalid_o,
  output logic [31:0] a_rdata_o,
  input  logic        b_req_i,
  input  logic        b_we_i,
  input  logic [3:0]  b_be_i,
  input  logic [31:0] b_addr_i,
  input  logic [31:0] b_wdata_i,
  output logic        b_rvalid_o,
  output logic [31:0] b_rdata_o
);
  logic [31:0] mem[Depth];
  always_ff @(posedge clk_i) begin
    if (a_req_i) begin
      if (a_we_i) begin
        for (int i = 0; i < 4; i++)
          if (a_be_i[i]) mem[a_addr_i[$clog2(Depth)-1+2:2]][i*8 +: 8] <= a_wdata_i[i*8 +: 8];
      end
      a_rdata_o <= mem[a_addr_i[$clog2(Depth)-1+2:2]];
    end
    a_rvalid_o <= a_req_i;
  end
  always_ff @(posedge clk_i) begin
    if (b_req_i) begin
      if (b_we_i) begin
        for (int i = 0; i < 4; i++)
          if (b_be_i[i]) mem[b_addr_i[$clog2(Depth)-1+2:2]][i*8 +: 8] <= b_wdata_i[i*8 +: 8];
      end
      b_rdata_o <= mem[b_addr_i[$clog2(Depth)-1+2:2]];
    end
    b_rvalid_o <= b_req_i;
  end
